<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/functions.php'; require_admin(); $payments=db()->query('SELECT p.*, u.email user_email, c.full_name FROM payments p JOIN users u ON u.id=p.user_id LEFT JOIN clients c ON c.id=p.client_id ORDER BY p.created_at DESC')->fetchAll(); ?>
<!doctype html><html><head><title>Revenue</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><h1>Revenue</h1><table><tr><th>Reference</th><th>User</th><th>Client</th><th>Amount</th><th>Status</th></tr><?php foreach($payments as $p): ?><tr><td><?= e($p['reference']) ?></td><td><?= e($p['user_email']) ?></td><td><?= e($p['full_name']) ?></td><td><?= e($p['currency']) ?> <?= number_format((float)$p['amount'],2) ?></td><td><?= e($p['status']) ?></td></tr><?php endforeach; ?></table></main></body></html>
